// Generated by usher — do not edit. Session-routing tools for the session
// designated as usher's router. The tool catalog is baked in from usher's Go
// source of truth at write time, and every call bridges to a
// `usher mcp-stdio --router-tools` child over newline JSON-RPC, so schemas,
// descriptions, and dispatch never fork from the MCP form.
import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { createInterface } from "node:readline";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const usherBin: string = __USHER_BIN__;
const hookSock: string = __USHER_HOOK_SOCK__;
const tools: { name: string; description: string; inputSchema: unknown }[] = __ROUTER_TOOLS_JSON__;

type Pending = { resolve: (v: unknown) => void; reject: (e: Error) => void };

// Bridge owns one lazily-spawned mcp-stdio child. A dead child is respawned
// on the next call; the protocol is stateless, so nothing is lost with it.
class Bridge {
	private child: ChildProcessWithoutNullStreams | null = null;
	private pending = new Map<number, Pending>();
	private seq = 0;

	private ensure(): ChildProcessWithoutNullStreams {
		if (this.child && this.child.exitCode === null) return this.child;
		const child = spawn(usherBin, ["mcp-stdio", "--router-tools"], {
			stdio: ["pipe", "pipe", "inherit"],
			env: { ...process.env, USHER_HOOK_SOCK: hookSock },
		});
		createInterface({ input: child.stdout }).on("line", (line) => {
			let msg: { id?: number; error?: { message?: string }; result?: unknown };
			try {
				msg = JSON.parse(line);
			} catch {
				return;
			}
			const p = msg.id === undefined ? undefined : this.pending.get(msg.id);
			if (!p || msg.id === undefined) return;
			this.pending.delete(msg.id);
			if (msg.error) p.reject(new Error(msg.error.message ?? "router tool call failed"));
			else p.resolve(msg.result);
		});
		child.on("close", () => {
			if (this.child === child) this.child = null;
			for (const p of this.pending.values()) p.reject(new Error("usher mcp-stdio exited"));
			this.pending.clear();
		});
		this.child = child;
		return child;
	}

	call(name: string, args: unknown): Promise<unknown> {
		const child = this.ensure();
		const id = ++this.seq;
		const req = { jsonrpc: "2.0", id, method: "tools/call", params: { name, arguments: args } };
		return new Promise((resolve, reject) => {
			this.pending.set(id, { resolve, reject });
			child.stdin.write(`${JSON.stringify(req)}\n`);
		});
	}
}

export default function usherRouterExtension(pi: ExtensionAPI) {
	const bridge = new Bridge();
	for (const tool of tools) {
		pi.registerTool({
			name: tool.name,
			label: tool.name,
			description: tool.description,
			// The catalog's inputSchema is plain JSON Schema, which is what
			// TypeBox schemas are at runtime.
			parameters: tool.inputSchema,
			async execute(_toolCallId: string, input: unknown) {
				const result = (await bridge.call(tool.name, input)) as {
					content?: { text?: string }[];
					isError?: boolean;
				} | null;
				const text = result?.content?.[0]?.text ?? JSON.stringify(result ?? null);
				if (result?.isError) throw new Error(text);
				return { content: [{ type: "text", text }] };
			},
			// biome-ignore lint/suspicious/noExplicitAny: generated bridge; the schema is validated by usher on the other side
		} as any);
	}
}
